using UnityEngine;
using UnityEngine.Tilemaps;
using Framework.Grid;
using Framework.Tilemap;
using Framework.Generation;

namespace Game.Tests
{
    /// <summary>
    /// 迷路生成システムとTilemap描画システムの
    /// 連携動作を確認するテストクラス。
    /// </summary>
    public class MazeGeneratorTest : MonoBehaviour
    {
        #region Fields

        [Header("迷路生成設定")]

        /// <summary>迷路の生成条件。</summary>
        [SerializeField]
        [Tooltip("迷路のサイズや生成条件を設定します。")]
        private MazeGenerationSettings settings =
            new MazeGenerationSettings();

        [Header("Tilemap設定")]

        /// <summary>床を描画するTilemap。</summary>
        [SerializeField]
        [Tooltip("床を描画するTilemap")]
        private Tilemap floorTilemap;

        /// <summary>壁を描画するTilemap。</summary>
        [SerializeField]
        [Tooltip("壁を描画するTilemap")]
        private Tilemap wallTilemap;

        [Header("タイル設定")]

        /// <summary>床として使用するタイル。</summary>
        [SerializeField]
        [Tooltip("床として使用するTileアセット")]
        private TileBase floorTile;

        /// <summary>壁として使用するタイル。</summary>
        [SerializeField]
        [Tooltip("壁として使用するTileアセット")]
        private TileBase wallTile;

        [Header("カメラ設定")]

        /// <summary>
        /// 迷路全体を表示するために調整するカメラ。
        /// 未設定の場合はカメラ調整を行わない。
        /// </summary>
        [SerializeField]
        [Tooltip("迷路全体を表示するカメラ")]
        private Camera targetCamera;

        /// <summary>迷路周囲に確保する余白。</summary>
        [SerializeField]
        [Min(0f)]
        [Tooltip("カメラ表示範囲に追加する余白")]
        private float cameraPadding = 1f;

        [Header("生成結果（確認用）")]

        /// <summary>最後に使用した乱数シード値。</summary>
        [SerializeField]
        [Tooltip("最後に生成した迷路のシード値")]
        private int lastSeed;

        /// <summary>最後に生成された迷路の情報。</summary>
        private MazeGenerationResult result;

        /// <summary>迷路描画用の汎用レンダラー。</summary>
        private GridTilemapRenderer<MazeCellType> mapRenderer;

        #endregion

        #region Unity Methods

        /// <summary>
        /// 再生開始時に迷路を生成する。
        /// </summary>
        private void Start()
        {
            GenerateMaze();
        }

        /// <summary>
        /// コンポーネント破棄時の終了処理。
        /// </summary>
        private void OnDestroy()
        {
            // 描画システムのイベント登録を解除する。
            mapRenderer?.Dispose();

            mapRenderer = null;
        }

        #endregion

        #region Generation Methods

        /// <summary>
        /// 現在の設定に従って迷路を生成し、
        /// Tilemapへ描画する。
        /// </summary>
        [ContextMenu("テスト/迷路を生成する")]
        public void GenerateMaze()
        {
            if (!Application.isPlaying)
            {
                Debug.LogWarning(
                    "再生モードで実行してください。",
                    this);

                return;
            }

            if (!ValidateSettings())
            {
                return;
            }

            // 迷路生成システムから生成結果を取得する。
            result = MazeGenerator.Generate(settings);

            // 使用したシード値を保存する。
            lastSeed = result.Seed;

            if (mapRenderer == null)
            {
                // 初回生成時は描画システムを作成する。
                CreateRenderer();
            }
            else
            {
                // 再生成時は古いマップを消去して
                // 新しいマップへ切り替える。
                mapRenderer.SetMap(result.Map);
            }

            // 生成された迷路を描画する。
            mapRenderer.RenderAll();

            // カメラの表示範囲を調整する。
            AdjustCamera();

            // 生成結果をConsoleへ出力する。
            PrintResult();

            // 迷路の基本構造を検証する。
            ValidateMaze();
        }

        /// <summary>
        /// 最後に生成した迷路のシード値を使用して
        /// 同じ迷路を再生成する。
        /// </summary>
        [ContextMenu("テスト/前回のシードで再生成する")]
        public void RegenerateLastSeed()
        {
            if (result == null)
            {
                Debug.LogWarning(
                    "迷路がまだ生成されていません。",
                    this);

                return;
            }

            // 元の乱数設定を一時保存する。
            bool previousFixedSeed = settings.UseFixedSeed;
            int previousSeed = settings.Seed;

            try
            {
                // 前回使用したシード値で生成する。
                settings.UseFixedSeed = true;
                settings.Seed = lastSeed;

                GenerateMaze();
            }
            finally
            {
                // 元の乱数設定を復元する。
                settings.UseFixedSeed = previousFixedSeed;
                settings.Seed = previousSeed;
            }
        }

        /// <summary>
        /// 描画システムを生成し、
        /// 床と壁の描画レイヤーを登録する。
        /// </summary>
        private void CreateRenderer()
        {
            mapRenderer =
                new GridTilemapRenderer<MazeCellType>(
                    result.Map,
                    true);

            // 床はすべてのマスに描画する。
            mapRenderer.AddLayer(
                floorTilemap,
                (position, cell) => floorTile);

            // 壁は壁データのマスにだけ描画する。
            mapRenderer.AddLayer(
                wallTilemap,
                (position, cell) =>
                    cell == MazeCellType.Wall
                        ? wallTile
                        : null);
        }

        #endregion

        #region Camera Methods

        /// <summary>
        /// 迷路全体がカメラの表示範囲に収まるように
        /// カメラの位置と表示サイズを調整する。
        ///
        /// 標準的なXY平面の2D Tilemapを想定する。
        /// </summary>
        private void AdjustCamera()
        {
            if (targetCamera == null || result == null)
            {
                return;
            }

            // マップの左下と右上のワールド座標を取得する。
            Vector3 bottomLeft = floorTilemap.CellToWorld(
                Vector3Int.zero);

            Vector3 topRight = floorTilemap.CellToWorld(
                new Vector3Int(
                    result.Width,
                    result.Height,
                    0));

            // マップの中心座標を算出する。
            Vector3 center =
                (bottomLeft + topRight) * 0.5f;

            // マップのワールド座標上の大きさを取得する。
            float worldWidth =
                Mathf.Abs(topRight.x - bottomLeft.x);

            float worldHeight =
                Mathf.Abs(topRight.y - bottomLeft.y);

            // 現在のカメラのZ座標を維持する。
            Vector3 cameraPosition =
                targetCamera.transform.position;

            cameraPosition.x = center.x;
            cameraPosition.y = center.y;

            targetCamera.transform.position = cameraPosition;

            // 正投影カメラとして設定する。
            targetCamera.orthographic = true;

            // 縦方向と横方向の両方が収まるサイズを求める。
            float verticalSize =
                worldHeight * 0.5f + cameraPadding;

            float horizontalSize =
                (worldWidth * 0.5f + cameraPadding) /
                Mathf.Max(0.01f, targetCamera.aspect);

            targetCamera.orthographicSize =
                Mathf.Max(verticalSize, horizontalSize);
        }

        #endregion

        #region Validation Methods

        /// <summary>
        /// Inspectorの設定内容を確認する。
        /// </summary>
        /// <returns>設定が有効な場合はtrue</returns>
        private bool ValidateSettings()
        {
            if (settings == null)
            {
                Debug.LogError(
                    "迷路生成設定が存在しません。",
                    this);

                return false;
            }

            if (floorTilemap == null || wallTilemap == null)
            {
                Debug.LogError(
                    "Tilemapが設定されていません。",
                    this);

                return false;
            }

            if (floorTilemap == wallTilemap)
            {
                Debug.LogError(
                    "床と壁には別々のTilemapを設定してください。",
                    this);

                return false;
            }

            if (floorTile == null || wallTile == null)
            {
                Debug.LogError(
                    "Tileアセットが設定されていません。",
                    this);

                return false;
            }

            return true;
        }

        /// <summary>
        /// 生成された迷路の基本構造を検証する。
        /// </summary>
        private void ValidateMaze()
        {
            // すべての通路が接続されているか確認する。
            bool connected =
                MazeGenerator.IsFullyConnected(result.Map);

            // 外周が壁として維持されているか確認する。
            bool borderValid = ValidateBorder(result.Map);

            Debug.Assert(
                connected,
                "接続されていない通路が存在します。",
                this);

            Debug.Assert(
                borderValid,
                "外周に通路が存在します。",
                this);

            Debug.Log(
                "【迷路検証結果】\n" +
                $"通路の接続性：{(connected ? "正常" : "異常")}\n" +
                $"外周の壁：{(borderValid ? "正常" : "異常")}",
                this);
        }

        /// <summary>
        /// 迷路の外周がすべて壁であるか確認する。
        /// </summary>
        /// <param name="map">検証対象の迷路</param>
        /// <returns>外周がすべて壁の場合はtrue</returns>
        private bool ValidateBorder(
            GridMap<MazeCellType> map)
        {
            foreach (Vector2Int position in map.GetPositions())
            {
                bool isBorder =
                    position.x == 0 ||
                    position.y == 0 ||
                    position.x == map.Width - 1 ||
                    position.y == map.Height - 1;

                if (isBorder &&
                    map.GetCell(position) != MazeCellType.Wall)
                {
                    return false;
                }
            }

            return true;
        }

        /// <summary>
        /// 同一の生成設定とシード値で
        /// 同じ迷路が生成されるか確認する。
        /// </summary>
        [ContextMenu("テスト/シード値の再現性を確認する")]
        public void TestSeedReproducibility()
        {
            if (!Application.isPlaying || settings == null)
            {
                return;
            }

            // 現在の設定を複製し、
            // 固定シードを有効にする。
            MazeGenerationSettings testSettings =
                new MazeGenerationSettings
                {
                    Width = settings.Width,
                    Height = settings.Height,
                    UseFixedSeed = true,
                    Seed = result != null
                        ? result.Seed
                        : settings.Seed,
                    LoopRate = settings.LoopRate,
                    DeadEndRemovalRate =
                        settings.DeadEndRemovalRate
                };

            // 同じ条件で迷路を2回生成する。
            MazeGenerationResult first =
                MazeGenerator.Generate(testSettings);

            MazeGenerationResult second =
                MazeGenerator.Generate(testSettings);

            bool isSame = true;

            // すべてのマスデータを比較する。
            foreach (Vector2Int position
                     in first.Map.GetPositions())
            {
                if (first.Map.GetCell(position) !=
                    second.Map.GetCell(position))
                {
                    isSame = false;
                    break;
                }
            }

            Debug.Assert(
                isSame,
                "同一シードで異なる迷路が生成されました。",
                this);

            Debug.Log(
                $"シード値の再現性：{(isSame ? "正常" : "異常")}",
                this);
        }

        #endregion

        #region Debug Methods

        /// <summary>
        /// 迷路の生成結果をConsoleへ出力する。
        /// </summary>
        private void PrintResult()
        {
            Debug.Log(
                "【迷路生成完了】\n" +
                $"マップサイズ：{result.Width} × {result.Height}\n" +
                $"シード値：{result.Seed}\n" +
                $"通路数：{result.PassageCount}\n" +
                $"壁数：{result.WallCount}\n" +
                $"行き止まり数：{result.DeadEndCount}\n" +
                $"追加通路数：{result.AddedPassageCount}\n" +
                $"通路割合：{result.PassageRate:P1}",
                this);
        }

        #endregion
    }
}
